import{_ as t,o as a,c as i,a5 as s}from"./chunks/framework.DbSlGjul.js";const u=JSON.parse('{"title":"Simulation assets","description":"","frontmatter":{},"headers":[],"relativePath":"simulation/assets.md","filePath":"simulation/assets.md","lastUpdated":1788882780000}'),r={name:"simulation/assets.md"};function o(n,e,d,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="simulation-assets" tabindex="-1">Simulation assets <a class="header-anchor" href="#simulation-assets" aria-label="Permalink to &quot;Simulation assets&quot;">​</a></h1><p>The main HiveBoard repository includes articulated digital assets for the physical mechanisms. Use these files when integrating HiveBoard into an existing simulator or robotics stack.</p><p>Browse the <a href="https://github.com/EESC-LabRoM/HiveBoard/tree/main/Simulation" target="_blank" rel="noreferrer"><code>Simulation/</code> directory</a>.</p><h2 id="available-mechanism-groups" tabindex="-1">Available mechanism groups <a class="header-anchor" href="#available-mechanism-groups" aria-label="Permalink to &quot;Available mechanism groups&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Folder</th><th>Mechanisms</th></tr></thead><tbody><tr><td><code>Button/</code></td><td>Covered push button</td></tr><tr><td><code>Circuit Breaker/</code></td><td>Toggle mechanism</td></tr><tr><td><code>Drawer/</code></td><td>Sliding drawer</td></tr><tr><td><code>Honeycomb/</code></td><td>Base geometry</td></tr><tr><td><code>Key/</code></td><td>Lock-and-key mechanism</td></tr><tr><td><code>Lamp/</code></td><td>Threaded light-bulb mechanism</td></tr><tr><td><code>Peg Insertion/</code></td><td>Threaded peg and socket</td></tr><tr><td><code>Shock Absorber/</code></td><td>Pin-insertion assembly</td></tr><tr><td><code>Threads/</code></td><td>M8 and M30 fasteners</td></tr><tr><td><code>Valves/</code></td><td>Ball and gate valves</td></tr></tbody></table><h2 id="model-contents" tabindex="-1">Model contents <a class="header-anchor" href="#model-contents" aria-label="Permalink to &quot;Model contents&quot;">​</a></h2><p>Depending on the mechanism, the simulation package provides:</p><ul><li>visual meshes;</li><li>collision meshes;</li><li>revolute, continuous, and prismatic joints;</li><li>joint ranges and limits;</li><li>nominal mass and inertia; and</li><li>URDF or USD exports.</li></ul><p>Threaded motion is represented by coupled rotational and translational joints where a native helical joint is unavailable. This reproduces the advance of a threaded component while keeping the asset portable across simulators.</p><h2 id="urdf-and-usd-assets" tabindex="-1">URDF and USD assets <a class="header-anchor" href="#urdf-and-usd-assets" aria-label="Permalink to &quot;URDF and USD assets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Starting point</th></tr></thead><tbody><tr><td>Load or visualize a mechanism in an existing stack</td><td>URDF or USD assets in the main repository</td></tr><tr><td>Inspect kinematics or create a custom environment</td><td>Articulated asset plus your simulator&#39;s loader</td></tr><tr><td>Train and evaluate policies in Isaac Lab</td><td>Dedicated Isaac Lab repository</td></tr><tr><td>Compare simulation with the printed board</td><td>Record model commit and locally identified physical parameters</td></tr></tbody></table><h2 id="physical-parameters" tabindex="-1">Physical parameters <a class="header-anchor" href="#physical-parameters" aria-label="Permalink to &quot;Physical parameters&quot;">​</a></h2><p>The provided masses, inertias, friction values, and contact properties are nominal. They are not system-identified values for every printed instance.</p><p>Printer calibration, filament, layer orientation, surface wear, sanding, and mechanism assembly can all change physical behavior. If close sim-to-real correspondence is required:</p><ol><li>print and assemble the target mechanism;</li><li>measure its range and actuation resistance;</li><li>identify the relevant simulation parameters;</li><li>store the overrides separately from the original asset; and</li><li>report both the asset commit and the identified values.</li></ol><h2 id="validation-before-use" tabindex="-1">Validation before use <a class="header-anchor" href="#validation-before-use" aria-label="Permalink to &quot;Validation before use&quot;">​</a></h2><p>Before training or evaluation, check that:</p><ul><li>every referenced mesh resolves;</li><li>the rest configuration has no unintended self-intersection;</li><li>joint axes and ranges match the physical mechanism;</li><li>collision geometry is sufficiently accurate for the task;</li><li>units and scale are correct; and</li><li>a full actuation cycle completes without instability.</li></ul><p>A simulation experiment must define observations, actions, reset states, success checks, termination conditions, and evaluation seeds.</p>',19)])])}const p=t(r,[["render",o]]);export{u as __pageData,p as default};
